create TABLE IF NOT EXISTS FLYWAY_SCHEMA_HISTORY (
	INSTALLED_RANK NUMBER(38,0) NOT NULL,
	VERSION VARCHAR(50),
	DESCRIPTION VARCHAR(200),
	TYPE VARCHAR(20) NOT NULL,
	SCRIPT VARCHAR(1000) NOT NULL,
	CHECKSUM NUMBER(38,0),
	INSTALLED_BY VARCHAR(100) NOT NULL,
	INSTALLED_ON TIMESTAMP_LTZ(9) NOT NULL DEFAULT CURRENT_TIMESTAMP(),
	EXECUTION_TIME NUMBER(38,0) NOT NULL,
	SUCCESS BOOLEAN NOT NULL,
	primary key (INSTALLED_RANK)
);
create view IF NOT EXISTS CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV(
	BRAND_ID COMMENT 'Brand Identifier specifies the code which represents an organization. The identifier should be in all capital letters. Sample codes are irb (Inspire Recognized Brands), bww(Buffalo Wild Wing), arbys (Arbys),  dnkn  (Dunkin), etc.',
	CMX_ID COMMENT 'CMX Identifier appears to uniquely identify the attribute combinations of group_name, report_tag, core_audit_service_service_name, and parent_item_id from the raw table. Sample values a7d51eab-f91e-4c98-91b3-510abf4b8bb0 and 7dbbab8a-484a-45a1-9fab-e8e4d070a202.',
	CMX_AUDIT_ID COMMENT 'CMX Audit Identifier  Sample values str-65f32bfe45b148cd9b541450fa2349a7 and str-ccf32239a76247a48231c223a00c9382.',
	STORE_ID COMMENT 'Store Identifier is an integer that uniquely identifies the store.',
	AUDIT_DT COMMENT 'Audit Date is the day of the audit.',
	CMX_AUDIT_SERVICE_NM COMMENT 'CMX Audit Service Name is a label for a type of audit. Sample values CTR PRE-Certification Audit, EcoSure (Self Assessment) 2021, and NCTR Certification Audit.',
	CMX_AUDIT_SERVICE_VERSION_NBR COMMENT 'CMX Audit Service Version Number is the version of an audit.',
	CMX_GROUP_NM COMMENT 'CMX Group Name is a high level categorization of questions. Sample values ARBY''S STANDARDS, FOOD SAFETY, and GUEST EXPERIENCE.',
	CMX_GROUP_POINT_QTY COMMENT 'CMX Group Point Quantity is the number of points for an audit that a restaraunt recieved at the Group Level.',
	CMX_GROUP_MAXIMUM_POINT_QTY COMMENT 'CMX Group Maximum Point Quantity is the maximum number of points for an audit that a restaraunt may receive at the Group Level.',
	CMX_GROUP_VAL COMMENT 'CMX Group Value  is a calculated value fromGroup Point Quantity and Group Maximum Point Quantity and store the percentage calculation. Examples of values are 93.32 and 87.65.',
	CMX_REPORT_TAG_NM COMMENT 'CMX Report Tag is a further categorization of audit question within a Group. NameSample values Building/Equipment/OSM Standards, Menu/Marketing, Equipment, Team Practices, Accuracy, and Cleanliness- Guest View.',
	CMX_REPORT_TAG_POINT_QTY COMMENT 'CMX Report Tag Point Quantity is the number of points for an audit that a restaraunt recieved at the Group/Report Tag Level.',
	CMX_REPORT_TAG_MAXIMUM_POINT_QTY COMMENT 'CMX Report Tag Maximum Point Quantity is the maximum number of points for an audit that a restaraunt may receive at the Group/Report Tag  Level.',
	CMX_REPORT_TAG_VAL COMMENT 'CMX Report Tag Value is a calculated value from Report Tag Point Quantity and Report Tag Maximum Point Quantity and store the percentage calculation. Examples of values are 93.32 and 87.65.',
	SOURCE_SYSTEM_NM COMMENT 'Source System Name specifies the origin of the data. For example, Salesforce Marketing App or Netsuite. Some systems will have a reference table where sources are identified by integers such as 1,2,3, etc.',
	LOAD_ID COMMENT 'Load Identifier specifies the Batch that inserted the record into the table.',
	LOAD_DTTM COMMENT 'Load Datetime is the date and time in UTC when the record was created. For example, 2021-08-11T15:02:24Z.',
	UPDATE_ID COMMENT 'Update Identifier specifies the batch id used for the update of the record.',
	UPDATE_DTTM COMMENT 'Update Datetime is the date and time in UTC when the record was last updated. For example, 2021-08-11T15:02:24Z.'
) COMMENT='CMX Restaurant Audit Report Tag Agg  is CMX audit aggregated data at the Group/Report Tag level.'
 as 
SELECT CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.BRAND_ID,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_ID,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_AUDIT_ID,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.STORE_ID,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.AUDIT_DT,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_AUDIT_SERVICE_NM,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_AUDIT_SERVICE_VERSION_NBR,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_GROUP_NM,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_GROUP_POINT_QTY,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_GROUP_MAXIMUM_POINT_QTY,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_GROUP_VAL,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_REPORT_TAG_NM,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_REPORT_TAG_POINT_QTY,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_REPORT_TAG_MAXIMUM_POINT_QTY,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.CMX_REPORT_TAG_VAL,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.SOURCE_SYSTEM_NM,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.LOAD_ID,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.LOAD_DTTM,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.UPDATE_ID,CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV.UPDATE_DTTM
FROM IDS_DEV.LOCN_BV.CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV ;
create view IF NOT EXISTS DDO_CMX_AUDIT_DETAIL_VAPP_V2(
	RPTG_AUDIT_KEY,
	RPTG_STORE_KEY,
	AUDIT_CATEGORY_DESC,
	CMX_ID,
	AUDIT_ID,
	STORE_ID,
	CMX_AUDIT_SERVICE_NM,
	CMX_AUDIT_SERVICE_VERSION_NBR,
	CMX_GROUP_NM,
	CMX_REPORT_TAG_NM,
	CMX_REPORT_TAG_POINT_QTY,
	CMX_REPORT_TAG_MAXIMUM_POINT_QTY,
	AUDIT_SCORE,
	AUDIT_DT_KEY,
	BRAND_ID,
	SOURCE_SYSTEM_NM,
	FISCAL_WEEK_NBR,
	FISCAL_YEAR_NBR,
	FISCAL_PERIOD_NBR,
	STORE_FRANCHISE_NM,
	STORE_FRANCHISE_ENTITY_NM,
	STORE_DIVISION,
	STORE_DMA_CD,
	STORE_DMA_DESC,
	STORE_BUILDING_TYPE,
	STORE_REMODEL_PROGRAM_NM,
	STORE_REMODEL_DT_KEY,
	FRANCHISE_CONSULTANT1_NAME,
	FRANCHISE_CONSULTANT2_NAME,
	FRANCHISE_CONSULTANT3_NAME,
	LEVEL1_NM,
	LEVEL1_MANAGER_NM,
	LEVEL2_NM,
	LEVEL2_MANAGER_NM,
	LEVEL3_NM,
	LEVEL3_MANAGER_NM,
	LEVEL4_NM,
	LEVEL4_MANAGER_NM,
	LEVEL5_NM,
	LEVEL5_MANAGER_NM,
	DVP
) as (
    WITH cmx_audit_cte AS (
        SELECT
            concat(brand_id, cmx_id, cmx_audit_id) as RPTG_AUDIT_KEY,
            concat(brand_id, lpad(store_id, 5, 0)) as RPTG_STORE_KEY,
            concat(cmx_group_nm, ':', cmx_report_tag_nm) as AUDIT_CATEGORY_DESC,
            cmx_id,
            cmx_audit_id as AUDIT_ID,
            lpad(store_id, 5, 0) as STORE_ID,
            cmx_audit_service_nm,
            cmx_audit_service_version_nbr,
            cmx_group_nm,
            cmx_report_tag_nm,
            cmx_report_tag_point_qty,
            cmx_report_tag_maximum_point_qty,
            cmx_report_tag_val as AUDIT_SCORE,
            to_char(audit_dt, 'YYYYMMDD') as AUDIT_DT_KEY,
            brand_id,
            source_system_nm
        FROM
            CMX_RESTAURANT_AUDIT_REPORT_TAG_AGG_BV
    ),
    RESTAURANT_CTE AS (
        SELECT
            STORE_ID,
            BRAND_ID,
            OWNERSHIP_TYP AS OWNERSHIP_TYPE,
            DMA_CD AS DMA_CODE,
            DMA_SOURCE_NM AS DMA_SOURCE_NAME,
            LEGAL_NM AS LEGAL_NAME,
            FRANCHISEE_NM AS FRANCHISEE_NAME,
            DIVISION_NM AS DIVISION_NAME,
            BUILDING_TYP AS BUILDING_TYPE,
            REMODEL_PROGRAM_TYP AS REMODEL_PROGRAM,
            REOPEN_DT AS REOPEN_DATE
        FROM IDM_DEV.COREDIM.RESTAURANT_SCD_DIM
        WHERE CURRENT_IND = TRUE
    ),
    HIERARCHY_CTE AS (
        SELECT
            LOCATION_ID AS LOCATIONID,
            BRAND_ID AS BRANDID,
            LEVEL1_NM AS L1NAME,
            LEVEL1_MANAGER_NM AS L1MANAGER,
            LEVEL2_NM AS L2NAME,
            LEVEL2_MANAGER_NM AS L2MANAGER,
            LEVEL3_NM AS L3NAME,
            LEVEL3_MANAGER_NM AS L3MANAGER,
            LEVEL4_NM AS L4NAME,
            LEVEL4_MANAGER_NM AS L4MANAGER,
            LEVEL5_NM AS L5NAME,
            LEVEL5_MANAGER_NM AS L5MANAGER,
            FRANCHISE_CONSULTANT1_NM AS FRANCHISE_CONSULTANT1_NAME,
            FRANCHISE_CONSULTANT2_NM AS FRANCHISE_CONSULTANT2_NAME,
            FRANCHISE_CONSULTANT3_NM AS FRANCHISE_CONSULTANT3_NAME
        FROM IDM_DEV.COREDIM.OPERATION_MANAGEMENT_HIERARCHY
    )
    SELECT
        cmx_audit.*,
        dateDim.fiscal_week_nbr,
        dateDim.fiscal_year_nbr,
        dateDim.fiscal_period_nbr,
        RESTAURANT.FRANCHISEE_NAME as STORE_FRANCHISE_NM,
        RESTAURANT.LEGAL_NAME as STORE_FRANCHISE_ENTITY_NM,
        UPPER(IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l3Name, RESTAURANT.DIVISION_NAME)) as STORE_Division,
        RESTAURANT.dma_code as store_dma_cd,
        RESTAURANT.dma_source_name as store_dma_desc,
        RESTAURANT.building_type as store_building_type,
        RESTAURANT.remodel_program as store_remodel_program_nm,
        RESTAURANT.reopen_date as store_remodel_dt_key,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Franchised', HIERARCHY.FRANCHISE_CONSULTANT1_NAME,NULL) AS FRANCHISE_CONSULTANT1_NAME,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Franchised', HIERARCHY.FRANCHISE_CONSULTANT2_NAME,NULL) AS FRANCHISE_CONSULTANT2_NAME,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Franchised', HIERARCHY.FRANCHISE_CONSULTANT3_NAME,NULL) AS FRANCHISE_CONSULTANT3_NAME,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l5Name,NULL) as level1_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l5manager,NULL) as level1_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l4Name,NULL) as level2_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l4manager,NULL) as level2_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l3Name,NULL) as level3_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l3manager,NULL) as level3_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l2Name,NULL) as level4_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l2manager,NULL) as level4_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l1Name,NULL) as level5_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l1manager,NULL) as level5_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Franchised', HIERARCHY.FRANCHISE_CONSULTANT3_NAME, HIERARCHY.l3manager) as DVP 
    FROM
        cmx_audit_cte as cmx_audit
        LEFT JOIN RESTAURANT_CTE as RESTAURANT ON
            cmx_audit.brand_id = RESTAURANT.brand_id
            AND cmx_audit.store_id::INTEGER = RESTAURANT.store_id::INTEGER
        LEFT JOIN HIERARCHY_CTE as HIERARCHY ON
            cmx_audit.brand_id = HIERARCHY.brandid
            AND cmx_audit.store_id::INTEGER = HIERARCHY.locationid::INTEGER
        LEFT JOIN IDH_DEV.SHARED.DATE_DIM_V as dateDim ON
            cmx_audit.AUDIT_DT_KEY = dateDim.date_key
);
