        AUDIT_CATEGORY_DESC,
        AUDIT_SCORE,
        FISCAL_WEEK_NBR,
        FISCAL_YEAR_NBR,
        FISCAL_PERIOD_NBR,
        STORE_FRANCHISE_NM,
        STORE_FRANCHISE_ENTITY_NM,
        STORE_Division,
        STORE_DMA_CD,
        STORE_DMA_DESC,
        STORE_BUILDING_TYPE,
        STORE_REMODEL_PROGRAM_NM,
        STORE_REMODEL_DT_KEY,
        FRANCHISE_CONSULTANT1_NAME,
        FRANCHISE_CONSULTANT2_NAME,
        FRANCHISE_CONSULTANT3_NAME,
        LEVEL1_NM,
        LEVEL1_MANAGER_NM,
        LEVEL2_NM,
        LEVEL2_MANAGER_NM,
        LEVEL3_NM,
        LEVEL3_MANAGER_NM,
        LEVEL4_NM,
        LEVEL4_MANAGER_NM,
        LEVEL5_NM,
        LEVEL5_MANAGER_NM,
        DVP
    FROM
        DDO_ECOSURE_AUDIT_DETAIL_VAPP_V2
);
create view IF NOT EXISTS DDO_ECOSURE_AUDIT_DETAIL_VAPP_V2(
	RPTG_AUDIT_KEY,
	RPTG_STORE_KEY,
	AUDIT_CATEGORY_DESC,
	AUDIT_ID,
	AUDIT_SCORE,
	AUDIT_DT_KEY,
	STORE_ID,
	BRAND_ID,
	SOURCE_SYSTEM_NM,
	FISCAL_WEEK_NBR,
	FISCAL_YEAR_NBR,
	FISCAL_PERIOD_NBR,
	STORE_FRANCHISE_NM,
	STORE_FRANCHISE_ENTITY_NM,
	STORE_DIVISION,
	STORE_DMA_CD,
	STORE_DMA_DESC,
	STORE_BUILDING_TYPE,
	STORE_REMODEL_PROGRAM_NM,
	STORE_REMODEL_DT_KEY,
	FRANCHISE_CONSULTANT1_NAME,
	FRANCHISE_CONSULTANT2_NAME,
	FRANCHISE_CONSULTANT3_NAME,
	LEVEL1_NM,
	LEVEL1_MANAGER_NM,
	LEVEL2_NM,
	LEVEL2_MANAGER_NM,
	LEVEL3_NM,
	LEVEL3_MANAGER_NM,
	LEVEL4_NM,
	LEVEL4_MANAGER_NM,
	LEVEL5_NM,
	LEVEL5_MANAGER_NM,
	DVP
) as (
    WITH ecosure_audit_cte AS (
        SELECT
            ecosure_rest_audit_score.brand_id || ecosure_rest_audit_score.ecosure_audit_id || ecosure_rest_audit_score.ecosure_score_nm as RPTG_AUDIT_KEY,
            ecosure_rest_audit_score.brand_id || lpad(ecosure_rest_audit.store_id, 5, 0) as RPTG_STORE_KEY,
            ecosure_rest_audit_score.ecosure_score_nm as AUDIT_CATEGORY_DESC,
            ecosure_rest_audit_score.ecosure_audit_id as AUDIT_ID,
            ecosure_rest_audit_score.ecosure_score_amt as AUDIT_SCORE,
            TO_VARCHAR(ecosure_rest_audit.audit_dt, 'YYYYMMDD') as AUDIT_DT_KEY,
            LPAD(ecosure_rest_audit.store_id, 5, 0) as STORE_ID,
            ecosure_rest_audit.brand_id as BRAND_ID,
            ecosure_rest_audit.source_system_nm as SOURCE_SYSTEM_NM
        FROM
            ECOSURE_RESTAURANT_AUDIT_SCORE_BV ecosure_rest_audit_score
            JOIN ECOSURE_RESTAURANT_AUDIT_BV ecosure_rest_audit ON ecosure_rest_audit_score.ecosure_audit_id = ecosure_rest_audit.ecosure_audit_id
    ),
    RESTAURANT_CTE AS (
        SELECT
            STORE_ID,
            BRAND_ID,
            OWNERSHIP_TYP AS OWNERSHIP_TYPE,
            DMA_CD AS DMA_CODE,
            DMA_SOURCE_NM AS DMA_SOURCE_NAME,
            LEGAL_NM AS LEGAL_NAME,
            FRANCHISEE_NM AS FRANCHISEE_NAME,
            DIVISION_NM AS DIVISION_NAME,
            BUILDING_TYP AS BUILDING_TYPE,
            REMODEL_PROGRAM_TYP AS REMODEL_PROGRAM,
            REOPEN_DT AS REOPEN_DATE
        FROM IDM_DEV.COREDIM.RESTAURANT_SCD_DIM
        WHERE CURRENT_IND = TRUE
    ),
    HIERARCHY_CTE AS (
        SELECT
            LOCATION_ID AS LOCATIONID,
            BRAND_ID AS BRANDID,
            LEVEL1_NM AS L1NAME,
            LEVEL1_MANAGER_NM AS L1MANAGER,
            LEVEL2_NM AS L2NAME,
            LEVEL2_MANAGER_NM AS L2MANAGER,
            LEVEL3_NM AS L3NAME,
            LEVEL3_MANAGER_NM AS L3MANAGER,
            LEVEL4_NM AS L4NAME,
            LEVEL4_MANAGER_NM AS L4MANAGER,
            LEVEL5_NM AS L5NAME,
            LEVEL5_MANAGER_NM AS L5MANAGER,
            FRANCHISE_CONSULTANT1_NM AS FRANCHISE_CONSULTANT1_NAME,
            FRANCHISE_CONSULTANT2_NM AS FRANCHISE_CONSULTANT2_NAME,
            FRANCHISE_CONSULTANT3_NM AS FRANCHISE_CONSULTANT3_NAME
        FROM IDM_DEV.COREDIM.OPERATION_MANAGEMENT_HIERARCHY
    )
    SELECT
        ecosure_audit.*,
        date_dim.fiscal_week_nbr,
        date_dim.fiscal_year_nbr,
        date_dim.fiscal_period_nbr,
        RESTAURANT.FRANCHISEE_NAME as STORE_FRANCHISE_NM,
        RESTAURANT.LEGAL_NAME as STORE_FRANCHISE_ENTITY_NM,
        UPPER(IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l3Name, RESTAURANT.DIVISION_NAME)) as STORE_Division,
        RESTAURANT.dma_code as store_dma_cd,
        RESTAURANT.dma_source_name as store_dma_desc,
        RESTAURANT.building_type as store_building_type,
        RESTAURANT.remodel_program as store_remodel_program_nm,
        RESTAURANT.reopen_date as store_remodel_dt_key,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Franchised', HIERARCHY.FRANCHISE_CONSULTANT1_NAME, NULL) AS FRANCHISE_CONSULTANT1_NAME,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Franchised', HIERARCHY.FRANCHISE_CONSULTANT2_NAME, NULL) AS FRANCHISE_CONSULTANT2_NAME,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Franchised', HIERARCHY.FRANCHISE_CONSULTANT3_NAME, NULL) AS FRANCHISE_CONSULTANT3_NAME,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l5Name, NULL) as level1_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l5manager, NULL) as level1_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l4Name, NULL) as level2_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l4manager, NULL) as level2_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l3Name, NULL) as level3_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l3manager, NULL) as level3_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l2Name, NULL) as level4_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l2manager, NULL) as level4_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l1Name, NULL) as level5_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Company Owned', HIERARCHY.l1manager, NULL) as level5_manager_nm,
        IFF(RESTAURANT.OWNERSHIP_TYPE='Franchised', HIERARCHY.FRANCHISE_CONSULTANT3_NAME, HIERARCHY.l3manager) as DVP 
    FROM
        ecosure_audit_cte AS ecosure_audit
        LEFT JOIN RESTAURANT_CTE as RESTAURANT
            ON RESTAURANT.brand_id = ecosure_audit.brand_id
            AND RESTAURANT.store_id::INTEGER = ecosure_audit.STORE_ID::INTEGER
        LEFT JOIN HIERARCHY_CTE as HIERARCHY ON
            ecosure_audit.brand_id = HIERARCHY.brandid
            AND HIERARCHY.locationid::INTEGER = ecosure_audit.STORE_ID::INTEGER
        LEFT JOIN IDH_DEV.SHARED.DATE_DIM_V date_dim 
            ON ecosure_audit.AUDIT_DT_KEY = date_dim.date_key
);
create view IF NOT EXISTS DIM_RESTAURANT_BV(
	RESTAURANT_KEY,
	REST_NUMBER,
	REST_NAME,
	REST_STATUS,
	REST_TYPE,
	REST_FRAN_NUMBER,
	REST_FRAN_NAME,
	REST_FRANENTITY_NUMBER,
	REST_FRANENTITY_NAME,
	REST_COMPANY_NAME,
	REST_BRAND_NAME,
	REST_BRAND_ISACTIVE,
	REST_DMA_CODE,
	REST_DMA_DESC,
	REST_ISAIRPORT,
	REST_ISVIDEOSURV,
	REST_ISBREAKFAST,
	REST_IS24HR,
	REST_ISMALL,
	REST_ISDRIVETHRU,
	REST_ADDRLINE1,
	REST_ADDRLINE2,
	REST_ADDRLINE3,
	REST_ADDRCITY,
