	STORE_COMPANY_NM COMMENT 'Store Company Name',
	STORE_BRAND_NM COMMENT 'Store Brand Name',
	STORE_DMA_CD COMMENT 'Store DMA Code',
	STORE_DMA_DESC COMMENT 'Store DMA Description',
	STORE_LATITUDE_NBR COMMENT 'Store Latitude Number',
	STORE_LONGITUDE_NBR COMMENT 'Store Longitude Number',
	STORE_BUILDING_TYP_NM COMMENT 'Store Building Type Name.  Sample values Pinnacle Blade, Inspire, Pinnacle Modified (PM), Pinnacle Look, Pinnacle Modified (PM) Look, Pinnacle, Series 2000, PM LOOK, TRAVEL PLAZA, Other.',
	STORE_REMODEL_PROGRAM_NM COMMENT 'Store Remodel Program Name',
