	STORE_ACQUISITION_DT_KEY COMMENT 'Store Acquisition Date Key.',
	STORE_FACILITY_TYP_NM COMMENT 'Store Facility Type Name. Sample values Conversion, Prototype, End-Cap.',
	STORE_SITE_TYP_NM COMMENT 'Store Site Type Name. Sample values Free Standing, C-Store, Travel Plaza, Shopping Center.',
	AREA_DESC COMMENT 'Corporate Store Area Description',
	AREA_NM COMMENT 'Corporate Store Area Name',
	DISTRICT_DESC COMMENT 'Corporate Store District Description',
	DISTRICT_NM COMMENT 'Corporate Store District Name',
	SUB_REGION_DESC COMMENT 'Corporate Store Sub Region Description',
	SUB_REGION_NM COMMENT 'Corporate Store Sub Region Name',
	REGION_DESC COMMENT 'Corporate Store Region Description',
	REGION_NM COMMENT 'Corporate Store Region Name',
	STORE_AREA_SUPERVISOR_NM COMMENT 'Corporate Store Area Supervisor Name',
	STORE_DO_NM COMMENT 'Corporate Store Director of Operations(DO) Name.',
	STORE_VPO_NM COMMENT 'Corporate Store Vice President of Operations(VPO) Name.',
	STORE_SVP_NM COMMENT 'Corporate Store Senior Vice President(SVP) Name.',
	FRANCHISE_TC_NM COMMENT 'Franchise Training Consultant (TC) Name.',
	FRANCHISE_OC_NM COMMENT 'Franchise Operations Consultant(OC) Name.',
	FRANCHISE_DFO_NM COMMENT 'Franchise Director of Franchise Operations(DFO) Name.',
	FRANCHISE_CONTACT_NM COMMENT 'Franchise Contact Name.',
	EFFECTIVE_BEGIN_DT COMMENT 'Effective Begin Date',
	EFFECTIVE_END_DT COMMENT 'Effective End Date',
	CURRENT_IND COMMENT 'Current Indicator',
	SOURCE_LOAD_ID COMMENT 'Source Load ID',
	SOURCE_UPDATE_DTTM COMMENT 'Source Last Update Date Time',
	BRAND_ID COMMENT 'Brand_Identifier'
) as 
